{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A focused intensive for building durable daily habits and gentle frameworks to sustain wellbeing in busy lives.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <nav class="nav">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <button class="nav-toggle" aria-expanded="false" aria-controls="nav-list">Menu</button>
      <ul id="nav-list" class="nav-list">
        <li><a href="/about.html">About</a></li>
        <li><a href="/programs.html">Programs</a></li>
        <li><a href="/services.html">Services</a></li>
        <li><a href="/pricing.html">Pricing</a></li>
        <li><a href="/testimonials.html">Stories</a></li>
        <li><a href="/book.html">Book</a></li>
        <li><a href="/contact.html">Contact</a></li>
      </ul>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <!-- Hero (split diagonal) -->
    <section class="hero" data-reveal>
      <div class="hero-inner split">
        <div class="split-pane left">
          <h1 class="hero-title">Gentle structures for dependable days</h1>
          <p class="hero-lead">Practical frameworks that focus on habits, rituals, and small shifts — designed to fit your schedule and values. A short intensive to create momentum and sustain it.</p>
          <div class="hero-cta-row">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Begin the intensive</a>
            <button id="try-now" class="btn ghost" aria-haspopup="dialog">Try it now</button>
          </div>
          <p class="hero-meta">Remote + in {{CITY}}, {{STATE}} • Coaching, habit plans, weekly check-ins</p>
        </div>
        <div class="split-pane right" aria-hidden="true">
          <div class="pattern-wrap" role="img" aria-label="Decorative pattern">
            <img src="assets/img/pattern.svg" alt="">
          </div>
        </div>
      </div>
    </section>

    <!-- Gallery -->
    <section class="gallery" data-reveal>
      <h2>Snapshots of the work</h2>
      <p class="muted">Tiny experiments, repeated with care. Visual prompts and short templates you can use immediately.</p>
      <div class="cards">
        <article class="card">
          <h3>Micro-routines</h3>
          <p>Two-minute rituals that anchor your mornings and close your evenings.</p>
        </article>
        <article class="card">
          <h3>Weekly architecture</h3>
          <p>A one-page plan to keep priorities visible and actionable.</p>
        </article>
        <article class="card">
          <h3>Focus scaffolds</h3>
          <p>Short templates to protect deep work without overhauling your calendar.</p>
        </article>
      </div>
    </section>

    <!-- What to expect -->
    <section class="what-to-expect" data-reveal>
      <h2>What to expect</h2>
      <ol>
        <li><strong>Early alignment:</strong> A focused intake to set human-centered priorities.</li>
        <li><strong>Practical frames:</strong> Clear habit architectures you can pilot in days.</li>
        <li><strong>Weekly calibration:</strong> Short check-ins to tune systems and keep momentum.</li>
      </ol>
      <p class="muted">Outcomes emphasize sustainable patterns, not temporary fixes. No medical advice — only behavioral practices and habit frameworks.</p>
    </section>

    <!-- Objections -->
    <section class="objections" data-reveal>
      <h2>Is this right for you?</h2>
      <div class="faq">
        <details>
          <summary>I don’t have time — will this add more tasks?</summary>
          <p>No. The intensive reframes small choices so they compound. We trade busywork for precise habit design.</p>
        </details>
        <details>
          <summary>I’ve tried programs before and they didn’t stick</summary>
          <p>This approach centers repeatable micro-actions and checkpoints so adjustments happen early and often.</p>
        </details>
        <details>
          <summary>Will I get a plan I can use alone?</summary>
          <p>Yes. You’ll leave with a suite of templates and a three-week self-run plan plus optional coaching follow-up.</p>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta" data-reveal>
      <div class="cta-inner">
        <h2>Ready for a focused reset?</h2>
        <p>Book an initial intensive session and walk away with a clear, small set of daily practices to test immediately.</p>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">Schedule the intensive</a>
        <p class="contact">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Work rooted in routine, tuned to your life.</p>
    <nav class="foot-nav">
      <a href="/about.html">About</a>
      <a href="/contact.html">Contact</a>
      <a href="/privacy.html">Privacy</a>
    </nav>
  </footer>

  <!-- Guided exercise modal -->
  <div id="exercise-modal" class="modal" role="dialog" aria-hidden="true" aria-labelledby="modal-title">
    <div class="modal-panel">
      <button class="modal-close" aria-label="Close">×</button>
      <h3 id="modal-title">Try a practice</h3>
      <p class="muted">Choose one short practice to feel how small frameworks can shift your state.</p>
      <div class="exercise-chooser">
        <button class="exercise-btn" data-exercise="breathing">Guided Breathing</button>
        <button class="exercise-btn" data-exercise="journaling">Micro-journaling</button>
        <button class="exercise-btn" data-exercise="intention">Intention setting</button>
      </div>
      <div id="exercise-area" class="exercise-area" aria-live="polite"></div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
