{"path":"assets/css/styles.css","content":"/* Core styles for split_diagonal layout, accessible, no external fonts */
:root{
  --bg:#0f1724; --card:#0b1220; --accent:#ffb86b; --muted:#9aa4b2; --text:#e6eef6; --glass:rgba(255,255,255,0.04);
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;background:linear-gradient(180deg,var(--bg) 0%, #07101a 100%);color:var(--text)}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(3,7,12,0.45),rgba(3,7,12,0.25));border-bottom:1px solid rgba(255,255,255,0.03);z-index:30}
.nav{max-width:var(--max-width);margin:0 auto;display:flex;align-items:center;gap:1rem;padding:1rem}
.logo{font-weight:700;color:var(--text);text-decoration:none}
.nav-list{list-style:none;margin:0;padding:0;display:flex;gap:.5rem;align-items:center}
.nav-list a{color:var(--muted);text-decoration:none;padding:.25rem .5rem;border-radius:6px}
.nav-list a:hover{color:var(--text);background:var(--glass)}
.nav-toggle{display:none}
.cta{margin-left:auto;background:linear-gradient(90deg,var(--accent),#ff7b6b);color:#10222a;padding:.5rem .75rem;border-radius:8px;text-decoration:none}

.main{padding:2rem}
.section{padding:4rem 1rem}
.hero{min-height:60vh;display:flex;align-items:center}
.hero-inner{max-width:var(--max-width);margin:0 auto;display:flex;align-items:stretch;gap:2rem}
.split{background:transparent;border-radius:12px;overflow:hidden}
.split-pane{flex:1;padding:2rem}
.split-pane.left{display:flex;flex-direction:column;justify-content:center}
.hero-title{font-size:clamp(1.5rem,3.5vw,2.5rem);margin:0 0 .5rem}
.hero-lead{color:var(--muted);margin:0 0 1rem}
.hero-cta-row{display:flex;gap:.75rem;align-items:center;margin-bottom:1rem}
.btn{padding:.6rem .9rem;border-radius:10px;border:0;cursor:pointer}
.btn.primary{background:linear-gradient(90deg,#ffd89b,#ff8a66);color:#042023}
.btn.ghost{background:transparent;color:var(--text);border:1px solid rgba(255,255,255,0.06)}
.btn.large{padding:1rem 1.25rem;font-weight:600}
.hero-meta{color:var(--muted);font-size:.9rem}
.pattern-wrap{width:100%;height:100%;display:flex;align-items:center;justify-content:center}
.pattern-wrap img{width:100%;height:100%;object-fit:cover;opacity:0.95}

.gallery{max-width:var(--max-width);margin:2rem auto;padding:2rem}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem;margin-top:1rem}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:1rem;border-radius:10px}
.card h3{margin:.25rem 0}
.muted{color:var(--muted)}

.what-to-expect, .objections, .final-cta{max-width:var(--max-width);margin:2rem auto;padding:2rem}
.faq details{background:var(--glass);padding:1rem;border-radius:8px;margin-bottom:.5rem}
.faq summary{cursor:pointer}

.site-footer{max-width:var(--max-width);margin:3rem auto;padding:2rem;color:var(--muted);display:flex;justify-content:space-between;align-items:center}
.foot-nav a{color:var(--muted);margin-left:1rem;text-decoration:none}

/* Modal */
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:linear-gradient(180deg,rgba(2,6,10,0.6),rgba(2,6,10,0.85));z-index:100}
.modal[aria-hidden="false"]{display:flex}
.modal-panel{background:#07101a;border:1px solid rgba(255,255,255,0.04);padding:1.25rem;border-radius:12px;max-width:520px;width:94%}
.modal-close{background:transparent;border:0;color:var(--muted);font-size:1.25rem;position:absolute;right:1rem;top:1rem}
.exercise-chooser{display:flex;gap:.5rem;margin:.75rem 0}
.exercise-btn{flex:1;padding:.6rem;border-radius:8px;background:var(--glass);border:1px solid rgba(255,255,255,0.03);color:var(--text)}
.exercise-area{min-height:120px;padding:.75rem;border-radius:8px;background:rgba(255,255,255,0.02);margin-top:.5rem}

/* Reveal animations */
[data-reveal]{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
[data-reveal].revealed{opacity:1;transform:none}

/* Respect reduced motion */
@media (prefers-reduced-motion: reduce){
  [data-reveal]{transition:none;opacity:1;transform:none}
}

/* Responsive */
@media(max-width:800px){
  .hero-inner{flex-direction:column}
  .nav-list{display:none}
  .nav-toggle{display:inline-block}
}

/* Decorative diagonal split via pseudo element */
.hero::after{content:'';position:absolute;inset:0;pointer-events:none;mix-blend-mode:overlay;opacity:.12;background:linear-gradient(135deg,transparent 40%, rgba(0,0,0,0.15) 60%)}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function qs(sel, ctx){ return (ctx||document).querySelector(sel); }
  function qsa(sel, ctx){ return Array.from((ctx||document).querySelectorAll(sel)); }

  // Set current year
  qs('#year').textContent = new Date().getFullYear();

  // Nav toggle for small screens
  var navToggle = qs('.nav-toggle');
  if(navToggle){
    navToggle.addEventListener('click', function(){
      var list = qs('#nav-list');
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', !expanded);
      list.style.display = expanded ? '' : 'flex';
    });
  }

  // Scroll-triggered reveal
  var revealEls = qsa('[data-reveal]');
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function onIntersect(entries, obs){
    entries.forEach(function(e){
      if(e.isIntersecting){
        e.target.classList.add('revealed');
        obs.unobserve(e.target);
      }
    });
  }

  if('IntersectionObserver' in window && !reduce){
    var io = new IntersectionObserver(onIntersect,{threshold:0.12});
    revealEls.forEach(function(el){ io.observe(el); });
  } else {
    // reveal immediately if reduced motion or no IO
    revealEls.forEach(function(el){ el.classList.add('revealed'); });
  }

  // Guided exercise modal
  var modal = qs('#exercise-modal');
  var tryBtn = qs('#try-now');
  var closeBtn = qs('.modal-close');
  var exerciseArea = qs('#exercise-area');
  var exerciseBtns = qsa('.exercise-btn');
  var activeTimer = null;

  function openModal(){
    modal.setAttribute('aria-hidden','false');
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    stopActive();
    exerciseArea.innerHTML = '';
  }
  function stopActive(){
    if(activeTimer){ clearInterval(activeTimer); activeTimer = null; }
  }

  tryBtn && tryBtn.addEventListener('click', openModal);
  closeBtn && closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e){ if(e.target===modal) closeModal(); });

  exerciseBtns.forEach(function(btn){
    btn.addEventListener('click', function(){
      var key = this.getAttribute('data-exercise');
      startExercise(key);
    });
  });

  // Exercises
  function startExercise(key){
    stopActive();
    exerciseArea.innerHTML = ''; 
    if(key==='breathing') startBreathing();
    else if(key==='journaling') startJournaling();
    else if(key==='intention') startIntention();
  }

  // Guided Breathing: 4-4-6 pattern with simple circle animation
  function startBreathing(){
    var container = document.createElement('div');
    container.className = 'breathing';
    container.innerHTML = '<div class="circle" aria-hidden="true"></div><p id="breath-text">Get comfortable. Close your eyes if you like.</p>';
    exerciseArea.appendChild(container);

    var text = qs('#breath-text', container);
    var circle = qs('.circle', container);

    var steps = [ {label:'Breathe in',sec:4},{label:'Hold',sec:4},{label:'Exhale',sec:6} ];
    var idx = 0;
    var secLeft = steps[0].sec;
    text.textContent = steps[0].label + ' — ' + secLeft;

    // Simple accessible animations: transform scale on circle, but respect reduced-motion
    var isReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    activeTimer = setInterval(function(){
      secLeft -= 1;
      if(secLeft<=0){
        idx = (idx+1) % steps.length;
        secLeft = steps[idx].sec;
      }
      text.textContent = steps[idx].label + ' — ' + secLeft;
      if(!isReduced){
        var scale = 1 + (Math.sin((Date.now()/600) + idx) * 0.08);
        circle.style.transform = 'scale(' + (1 + ((steps[idx].label==='Breathe in')?0.25:(steps[idx].label==='Exhale')?0.75:0.55)) + ')';
      }
    },1000);
  }

  // Micro-journaling: prompt + countdown (90s)
  function startJournaling(){
    var prompts = [
      'What small wins did I notice this week?',
      'One thing I can simplify tomorrow is…',
      'Where did I spend energy that didn’t match my priorities?'
    ];
    var p = prompts[Math.floor(Math.random()*prompts.length)];
    var container = document.createElement('div');
    container.innerHTML = '<p><strong>Prompt:</strong> ' + p + '</p><p id="journal-timer">90</p><textarea placeholder="Write for 90 seconds..." rows="6" style="width:100%;margin-top:.5rem;border-radius:8px;padding:.5rem;background:#06121a;border:1px solid rgba(255,255,255,0.03);color:var(--text)"></textarea>';
    exerciseArea.appendChild(container);
    var timer = qs('#journal-timer', container);
    var t = 90;
    activeTimer = setInterval(function(){ t--; timer.textContent = t; if(t<=0){ clearInterval(activeTimer); activeTimer=null; timer.textContent='Done — take a breath.' } },1000);
  }

  // Intention setting: three affirmations with soft timer
  function startIntention(){
    var container = document.createElement('div');
    container.innerHTML = '<ol id="int-list"></ol><p id="int-timer" class="muted">20</p>';
    exerciseArea.appendChild(container);
    var list = qs('#int-list', container);
    var timer = qs('#int-timer', container);
    var intentions = ['I will choose one clear priority today.','I will protect one hour of focused effort.','I will rest with purpose tonight.'];
    var idx = 0; var t = 20;
    list.innerHTML = '<li>' + intentions[0] + '</li>';
    activeTimer = setInterval(function(){ t--; timer.textContent = t; if(t<=0){ idx++; t=20; if(idx>=intentions.length){ clearInterval(activeTimer); activeTimer=null; timer.textContent='Done — keep one intention visible.'; } else { list.innerHTML += '<li>' + intentions[idx] + '</li>'; timer.textContent = t; } } },1000);
  }

})();"} 
